using System.Net;using System.Net.Http.Json;using Microsoft.Extensions.DependencyInjection;using Microsoft.EntityFrameworkCore;using RaceDay.Api.Data;using Xunit;
namespace RaceDay.Tests;
public class RaceDayApiTests: IClassFixture<ApiFactory>{private readonly ApiFactory f;public RaceDayApiTests(ApiFactory factory){f=factory;f.SeedAsync().GetAwaiter().GetResult();}
 [Fact] public async Task Registration_CreatesParticipantAndCanLogin(){using var c=f.CreateClient();var email=$"new{Guid.NewGuid():N}@test.local";var r=await c.PostAsJsonAsync("/api/auth/register",new{firstName="Nina",lastName="New",email,password="Password123!"});Assert.Equal(HttpStatusCode.Created,r.StatusCode);var login=await c.PostAsJsonAsync("/api/auth/login",new{email,password="Password123!"});Assert.Equal(HttpStatusCode.OK,login.StatusCode);}
 [Fact] public async Task InvalidLogin_ReturnsUnauthorized(){using var c=f.CreateClient();var r=await c.PostAsJsonAsync("/api/auth/login",new{email="missing@test.local",password="WrongPassword1!"});Assert.Equal(HttpStatusCode.Unauthorized,r.StatusCode);}
 [Fact] public async Task Participant_CannotCreateEvent(){var token=await f.LoginAsync("participant@raceday.test","Participant123!");using var c=f.AuthClient(token);var r=await c.PostAsJsonAsync("/api/events",new{eventName="Forbidden event",description="",eventDate=DateTime.UtcNow.Date.AddDays(20),location="Cape Town"});Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);}
 [Fact] public async Task Organiser_CanCreateEvent(){var token=await f.LoginAsync("organiser@raceday.test","Organiser123!");using var c=f.AuthClient(token);var r=await c.PostAsJsonAsync("/api/events",new{eventName="New test event",description="Test",eventDate=DateTime.UtcNow.Date.AddDays(20),location="Cape Town"});Assert.Equal(HttpStatusCode.Created,r.StatusCode);}
 [Fact] public async Task Participant_CanEnrolAndEnrolmentIsRecorded(){var token=await f.LoginAsync("participant@raceday.test","Participant123!");using var c=f.AuthClient(token);var r=await c.PostAsJsonAsync("/api/enrolments",new{eventID=1,categoryID=1});Assert.Equal(HttpStatusCode.Created,r.StatusCode);var mine=await c.GetAsync("/api/enrolments/mine");Assert.Equal(HttpStatusCode.OK,mine.StatusCode);var json=await mine.Content.ReadAsStringAsync();Assert.Contains("Test Run",json);}
 [Fact] public async Task Organiser_CanRecordResultAndParticipantCanViewOwnResult(){var orgToken=await f.LoginAsync("organiser@raceday.test","Organiser123!");var pToken=await f.LoginAsync("participant@raceday.test","Participant123!");using var p=f.AuthClient(pToken);var enrol=await p.PostAsJsonAsync("/api/enrolments",new{eventID=1,categoryID=1});Assert.Equal(HttpStatusCode.Created,enrol.StatusCode);using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<RaceDayContext>();var e=await db.Enrolments.FirstAsync(x=>x.ParticipantID==2);using var org=f.AuthClient(orgToken);var result=await org.PutAsJsonAsync($"/api/results/enrolment/{e.EnrolmentID}",new{finishTime="00:25:30",position=1,status="Recorded"});Assert.Equal(HttpStatusCode.OK,result.StatusCode);var own=await p.GetAsync("/api/results/mine");Assert.Equal(HttpStatusCode.OK,own.StatusCode);Assert.Contains("00:25:30",await own.Content.ReadAsStringAsync());}
 [Fact] public async Task UnauthenticatedUser_CannotReadProfile(){using var c=f.CreateClient();var r=await c.GetAsync("/api/auth/me");Assert.Equal(HttpStatusCode.Unauthorized,r.StatusCode);}
 [Fact] public async Task Participant_SeesOnlyOwnResults(){var token=await f.LoginAsync("participant@raceday.test","Participant123!");using var c=f.AuthClient(token);var r=await c.GetAsync("/api/results");Assert.Equal(HttpStatusCode.OK,r.StatusCode);}
}
